// 속성 EL 실현 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_attrReals
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_attrReals = async function () {
    const attrRealsList = [{ childId: "__rb0", attr: "label", fn: function () { return String(dma_defaultMap.get("comNm")) + "(" + String(dma_defaultMap.get("isurCd")) + ")"; } },
        { childId: "__rb1", attr: "label", fn: function () { return String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["usrId"] ?? "") + "/" + String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["corpUsrNm"] ?? ""); } },
        { childId: "__rb2", attr: "label", fn: function () { return String(dma_defaultMap.get("mktTpNm")); } },
        { childId: "__rb3", attr: "label", fn: function () { return String(dma_defaultMap.get("secugrpNm")); } }];
    const root = (function () { try { const f = $c.win.getFrame(); return (f && f.render) ? f.render : null; } catch (e) { return null; } })();
    const hasText = function (t) { return /[가-힣A-Za-z0-9]/.test(String(t == null ? "" : t)); };
    let applied = 0;
    for (let i = 0; i < attrRealsList.length; i++) {
        const a = attrRealsList[i];
        const comp = $c.util.getComponent(a.childId);
        const el = (comp && comp.getID && root) ? root.querySelector("#" + comp.getID()) : null;
        if (!comp && !el) { console.warn("[sdd] 속성 실현 대상 부재: " + a.childId); continue; }
        let v;
        try { v = a.fn(); } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId + "." + a.attr }); continue; }
        if (a.attr === "style") {
            if (comp && typeof comp.setStyle === "function") {
                const decls = String(v).split(";");
                for (let di = 0; di < decls.length; di++) {
                    const kv = decls[di].split(":");
                    if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
                }
            } else if (el) { el.style.cssText = (el.style.cssText || "") + ";" + v; }
        } else if (a.attr === "label") {
            if (comp && typeof comp.setValue === "function") { comp.setValue(v); } else if (el) { el.textContent = v; }
        } else if (a.attr === "__value") {
            if (comp && typeof comp.setValue === "function") { comp.setValue(v); }
        } else if (a.attr === "__items") {
            if (comp && typeof comp.addItem === "function" && v && v.length) {
                let hasVal = false;
                for (let ii = 0; ii < v.length; ii++) { if (hasText(v[ii][0]) || hasText(v[ii][1])) { hasVal = true; break; } }
                if (hasVal) {
                    if (typeof comp.removeAll === "function") { comp.removeAll(); }
                    for (let ij = 0; ij < v.length; ij++) {
                        const lb = String(v[ij][1] || "");
                        comp.addItem(String(v[ij][0] || ""), hasText(lb) ? lb : "");
                    }
                }
            }
        } else if (a.attr === "class") {
            if (el) { el.className = v; }
        } else if (a.attr === "__html") {
            if (el && !el.querySelector('[class*="w2"], input, select, textarea, button')) { el.innerHTML = v; }
        } else if (el) {
            el.setAttribute(a.attr, v);
            if (a.attr === "src" && el.tagName === "IMG") { el.src = v; }
        }
        applied++;
    }
    return applied;
};

// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "ipt_parval", fn: function(){ return ((dma_defaultMap.get("secugrpId") ?? (() => { throw new Error("unresolved:" + "defaultMap.secugrpId"); })()) ==='ST' || (dma_defaultMap.get("secugrpId") ?? (() => { throw new Error("unresolved:" + "defaultMap.secugrpId"); })()) ==='RT'); } }, { id: "ipt_parval_2", fn: function(){ return ((dma_defaultMap.get("secugrpId") ?? (() => { throw new Error("unresolved:" + "defaultMap.secugrpId"); })()) ==='FS' || (dma_defaultMap.get("secugrpId") ?? (() => { throw new Error("unresolved:" + "defaultMap.secugrpId"); })()) ==='DR'); } }, { id: "if_listTpClssCd", fn: function(){ return ((dma_comInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "comInfo.listTpClssCd"); })()) !== '02' && (dma_comInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "comInfo.listTpClssCd"); })()) !== '06'); } }, { id: "tr_109", fn: function(){ return ((dma_comInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "comInfo.listTpClssCd"); })()) !== '02' && (dma_comInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "comInfo.listTpClssCd"); })()) !== '06'); } }, { id: "tr_118", fn: function(){ return ((dma_comInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "comInfo.listTpClssCd"); })()) !== '02' && (dma_comInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "comInfo.listTpClssCd"); })()) !== '06'); } }, { id: "if_secugrpId", fn: function(){ return ((dma_comInfo.get("secugrpId") ?? (() => { throw new Error("unresolved:" + "comInfo.secugrpId"); })()) !== 'RT'); } }, { id: "tr_161", fn: function(){ return ((dma_comInfo.get("secugrpId") ?? (() => { throw new Error("unresolved:" + "comInfo.secugrpId"); })()) !== 'RT'); } }, { id: "tr_182", fn: function(){ return ((dma_comInfo.get("secugrpId") ?? (() => { throw new Error("unresolved:" + "comInfo.secugrpId"); })()) !== 'RT'); } }, { id: "tr_196", fn: function(){ return ((dma_comInfo.get("secugrpId") ?? (() => { throw new Error("unresolved:" + "comInfo.secugrpId"); })()) !== 'RT'); } }, { id: "if_listTpClssCd_2", fn: function(){ return ((dma_comInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "comInfo.listTpClssCd"); })()) !== '02'  && (dma_comInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "comInfo.listTpClssCd"); })()) !== '06'); } }, { id: "tr_125", fn: function(){ return ((dma_comInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "comInfo.listTpClssCd"); })()) !== '02'  && (dma_comInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "comInfo.listTpClssCd"); })()) !== '06'); } }, { id: "tr_146", fn: function(){ return ((dma_comInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "comInfo.listTpClssCd"); })()) !== '02'  && (dma_comInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "comInfo.listTpClssCd"); })()) !== '06'); } }, { id: "tr_153", fn: function(){ return ((dma_comInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "comInfo.listTpClssCd"); })()) !== '02'  && (dma_comInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "comInfo.listTpClssCd"); })()) !== '06'); } }, { id: "tr_161", fn: function(){ return ((dma_comInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "comInfo.listTpClssCd"); })()) !== '02'  && (dma_comInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "comInfo.listTpClssCd"); })()) !== '06'); } }, { id: "tr_182", fn: function(){ return ((dma_comInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "comInfo.listTpClssCd"); })()) !== '02'  && (dma_comInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "comInfo.listTpClssCd"); })()) !== '06'); } }, { id: "tr_196", fn: function(){ return ((dma_comInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "comInfo.listTpClssCd"); })()) !== '02'  && (dma_comInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "comInfo.listTpClssCd"); })()) !== '06'); } }, { id: "tr_203", fn: function(){ return ((dma_comInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "comInfo.listTpClssCd"); })()) !== '02'  && (dma_comInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "comInfo.listTpClssCd"); })()) !== '06'); } }, { id: "tr_210", fn: function(){ return ((dma_comInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "comInfo.listTpClssCd"); })()) !== '02'  && (dma_comInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "comInfo.listTpClssCd"); })()) !== '06'); } }, { id: "if_listTpClssCd_4", fn: function(){ return ((dma_comInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "comInfo.listTpClssCd"); })()) !== '02'  && (dma_comInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "comInfo.listTpClssCd"); })()) !== '06'); } }, { id: "btn_Register", fn: function(){ return ((dma_comInfo.get("listProcsStat") ?? (() => { throw new Error("unresolved:" + "comInfo.listProcsStat"); })()) != 32 && (dma_comInfo.get("listProcsStat") ?? (() => { throw new Error("unresolved:" + "comInfo.listProcsStat"); })()) != 33 && (dma_comInfo.get("listProcsStat") ?? (() => { throw new Error("unresolved:" + "comInfo.listProcsStat"); })()) != 34 && (dma_comInfo.get("listProcsStat") ?? (() => { throw new Error("unresolved:" + "comInfo.listProcsStat"); })()) != 36); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

