/**
 * @method
 * @name scwin.checkForm
 * @author Inswave
 * @date 2026. 09. 29
 * @param frm
 * @returns
 * @hidden N
*/
scwin.checkForm = async function (frm) {
    /* sdd-asis-lifecycle:begin checkForm — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const vFields = {};
    /* 수동 전환 필요: recentAcntgPdStrtYymm option:isyymmdate — 엔진 대응 미상 */
    /* 수동 전환 필요: recentAcntgPdEndYymm option:isyymmdate — 엔진 대응 미상 */
    /* 수동 전환 필요: nparvalstkYn 필수 검사 — 입력 컴포넌트 미이관 */
    vFields["ipt_recentAcntgPdStrtYymm"] = { required: false };
    const result = await $c.validate.validateDataCollect($c.util.getComponent("form_5"), { validateType: 'alert', checkType: 'single', focus: true, fields: vFields });
    if (!result) {
        console.error("[sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완");	return false;
    } else {
        return true;
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.prelistPageSearch
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.prelistPageSearch = async function () {
    /* sdd-asis-lifecycle:begin fn_PrelistPageSearch — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.preListForm || { elements: [] });
    const gongmo = $c.util.getComponent('dma_PrelistPageSearchReq').get('gongMo');
    $c.util.getComponent('dma_PrelistPageSearchReq').set('method', "listPrelmInvstgList");
    if (gongmo === "Y") {
        $c.util.getComponent('dma_PrelistPageSearchReq').set('page', "konexGongsamo");
    } else {
        $c.util.getComponent('dma_PrelistPageSearchReq').set('page', "konex");
    }
    await scwin.tx_fn_PrelistPageSearch();
    /* sdd-asis-lifecycle:end */
};
